import React from 'react';
import {useS,T,en,idx,DUR,words,AbsoluteFill,Textura,Profundidad,Brillo,Paso,Entrar,Chip,Contador,tono,FONT} from './kit';

export const SUBS={arriba:230,acento:'#FFC83D'};
const ARR=[0,9,30,42,62,83,99,123,154];
export const CORTES=ARR.slice(1).map(i=>T(i)-0.1);
const GOLD='#FFC83D';
const at=(w:string,e:number,n=1)=>en(w,n,ARR[e]);
const soundNames=['tick_01','click_02','tick_02','click_03'];
// Un sonido por cada acción secundaria, siempre en una palabra real; sin duplicar ataques.
const accents=[{t:T(0),s:'whoosh_01'},{t:at('propina',0),s:'pop_01'},
 {t:at('Compraste',1),s:'papel_02'},{t:at('Dieciocho',1),s:'click_01'},
 {t:at('veinte',1),s:'click_02'},{t:at('veinticinco',1),s:'click_03'},
 {t:T(30),s:'whoosh_02'},{t:at('Así',3),s:'whoosh_03'},
 {t:at('tocas',3),s:'click_04'},{t:at('propósito',3),s:'ding_01'},
 {t:T(62),s:'whoosh_04'},{t:at('siete',4),s:'tick_02'},
 {t:at('uno',5),s:'chime_01'},{t:at('suma',6),s:'whoosh_05'},
 {t:at('sesenta',6),s:'ding_03'},{t:T(123),s:'whoosh_06'},
 {t:at('cantidad',7),s:'click_04'},{t:at('escribe',7),s:'chime_02'},
 {t:T(154),s:'whoosh_01'}];
export const SFX=[...accents,...words.flatMap((w,i)=>i%2===0&&!accents.some(a=>Math.abs(a.t-w.t)<0.29)?[{t:w.t,s:soundNames[Math.floor(i/2)%soundNames.length]}]:[])].sort((a,b)=>a.t-b.t).filter((v,i,a)=>!i||v.t-a[i-1].t>=0.27);

const Defs=()=> <defs>
 <linearGradient id="case" x2="1" y2="1"><stop stopColor="#69747c"/><stop offset=".3" stopColor="#212b31"/><stop offset="1" stopColor="#080d12"/></linearGradient>
 <linearGradient id="glass" x2=".8" y2="1"><stop stopColor="#34484f"/><stop offset=".45" stopColor="#14232b"/><stop offset="1" stopColor="#0a151e"/></linearGradient>
 <linearGradient id="cup" x2="1"><stop stopColor="#d4c5a9"/><stop offset=".35" stopColor="#fff6df"/><stop offset="1" stopColor="#c4b697"/></linearGradient>
 <linearGradient id="skin" x2="1" y2=".6"><stop stopColor="#ffe0be"/><stop offset=".5" stopColor="#e6ad85"/><stop offset="1" stopColor="#ad6f50"/></linearGradient>
 <linearGradient id="leather" x2=".5" y2="1"><stop stopColor="#af6f3e"/><stop offset=".5" stopColor="#64351e"/><stop offset="1" stopColor="#271a15"/></linearGradient>
 <radialGradient id="gold"><stop stopColor="#fff1a6"/><stop offset="1" stopColor="#c89122"/></radialGradient>
 <linearGradient id="money" x2="1" y2="1"><stop stopColor="#e2e9bc"/><stop offset="1" stopColor="#76927a"/></linearGradient>
 </defs>;

