 return <g transform={`translate(${x} ${y}) scale(${scale})`}>
 <ellipse cy="225" rx="125" ry="22" fill="#130e0c" opacity=".35"/>
 <path d="M-110-135 L-82 200 Q0 230 82 200 L110-135Z" fill="url(#cup)"/>
 <path d="M-101-40 L-91 100 Q0 122 91 100 L101-40Z" fill={lit?GOLD:'#8b5739'}/>
 <path d="M-91-30Q0-8 91-30M-86 90Q0 112 86 90" fill="none" stroke="#e0b57b" strokeWidth="4"/>
 <ellipse cy="-136" rx="119" ry="28" fill="#1f2528"/>
 <path d="M-117-138L-105-169Q0-190 105-169L117-138" fill="#414b4c"/>
 <ellipse cy="-170" rx="104" ry="18" fill="#66716e"/>
 <rect x="35" y="-179" width="39" height="8" rx="4" fill="#111a1e"/>
 {[0,1,2].map(i=><path key={i} d={`M${-40+i*40} -210q${24*Math.sin(s+i)} -45 0 -100`} stroke="#fff3db" strokeWidth="7" opacity=".19" fill="none"/>)}
