};

const Bill:React.FC<{x:number;y:number;r?:number}>=({x,y,r=0})=><g transform={`translate(${x} ${y}) rotate(${r})`}>
 <rect x="-180" y="-72" width="360" height="144" rx="8" fill="url(#money)"/>
