 </g>;

const Tablet:React.FC<{e:number;small?:boolean}>=({e,small=false})=>{
 const {s,spr,lin}=useS();
 const sol=e===7, end=e===8;
 const p=sol?lin(at('otra',7),at('escribe',7),0,1):0;
 const angle=e===0?lin(T(0),at('propina',0),-164,0):end?lin(T(154),DUR,0,165):0;
 const on=e!==0||s>=at('propina',0);
 const bump=e===3?spr(at('veinticinco',3)):0;
 return <g transform={`translate(540 1040) scale(${small?.8:1})`}>
 <ellipse cy="465" rx="360" ry="48" fill="#100c0b" opacity=".4"/>
 <path d="M-62 260L-104 421H126L61 260" fill="url(#case)"/>
 <ellipse cy="419" rx="166" ry="27" fill="#435056"/>
 <g style={{transform:`perspective(1800px) rotateY(${angle}deg)`,transformOrigin:'0px 0px'}}>
 <rect x="-445" y="-420" width="890" height="710" rx="49" fill="url(#case)" stroke="#839294" strokeWidth="4"/>
 <g opacity={Math.abs(angle)<89?1:0}>
 <rect x="-414" y="-389" width="828" height="647" rx="28" fill="url(#glass)"/>
 <circle cy="-405" r="6" fill="#0b1115"/>
 <path d="M-390-370L-30-370L-280 240H-390Z" fill="#f5f5e0" opacity=".045"/>
 <text y="-263" textAnchor="middle" fontSize="46" fill="#e4e8dc" fontFamily={FONT}>Propina</text>
 {[18,20,25].map((n,i)=>{
 const a=e===1?spr(at(['Dieciocho','veinte','veinticinco'][i],1)):on?1:0;
 const x=-260+i*260;
 const k=i===2?1+bump*.15:i===1?1-bump*.09:1;
 return <g key={n} transform={`translate(${x} ${-58+(1-a)*-115}) scale(${k})`} opacity={a*(1-p*.82)}>
 <rect x="-113" y="-107" width="226" height="214" rx="25" fill={i===1&&e===3?'#fff3b0':'url(#gold)'} stroke="#ffefa3" strokeWidth="3"/>
 <text y="13" textAnchor="middle" fill="#392b15" fontSize="55" fontWeight="800" fontFamily={FONT}>{n}%</text>
 </g>;
 })}
 <g opacity={sol?Math.max(.4,p):.33}>
 <rect x="-370" y="128" width="340" height="82" rx="17" fill={sol?'#d5ddcc':'#34434a'}/>
 <text x="-200" y="181" textAnchor="middle" fontSize="31" fill={sol?'#16342e':'#b9c7c3'} fontFamily={FONT}>Sin propina</text>
 <rect x="30" y="128" width="340" height="82" rx="17" fill={sol?GOLD:'#34434a'}/>
 <text x="200" y="181" textAnchor="middle" fontSize="31" fill={sol?'#3a2911':'#b9c7c3'} fontFamily={FONT}>Otra cantidad</text>
 </g>
 {sol&&s>at('escribe',7)&&<g><rect x="-112" y="-110" width="224" height="125" rx="18" fill="#eaf1de"/><text y="-25" textAnchor="middle" fill="#1c4437" fontSize="70" fontFamily={FONT}>$1</text><path d="M-62 30h124" stroke={GOLD} strokeWidth="5"/></g>}
 </g>
 {Math.abs(angle)>=89&&<g><rect x="-398" y="-373" width="796" height="612" rx="32" fill="#27343b"/><circle r="35" fill="#4c5a5f"/><path d="M-180 205h360" stroke="#718084" strokeWidth="5"/></g>}
 </g>
 </g>;
};

const Queue=()=>{
 const {s,spr}=useS();
 return <g>
 {[0,1,2,3].map((i)=><g key={i} transform={`translate(${180+i*235+Math.sin(s*.3+i)*8} ${860-i%2*120}) scale(${.7-i*.055})`} opacity={.7-i*.09}>
 <path d="M-135 430q-20-260 62-300h146q93 60 62 300" fill={['#8f9b83','#ae7451','#707b9e','#9c8f79'][i]}/>
 <rect x="-30" y="65" width="60" height="91" rx="20" fill={['#714c38','#d8aa87','#a67b54','#e0bca0'][i]}/>
 <ellipse cy="0" rx="79" ry="110" fill={['#714c38','#d8aa87','#a67b54','#e0bca0'][i]}/>
 <path d="M-79-10q-20-126 75-120q105 0 82 134q-13-69-53-66q-52 30-104 5" fill="#262424"/>
 <g opacity={spr(at('fila',2))}>{[-30,30].map(x=><g key={x}><ellipse cx={x} cy="-5" rx="19" ry="10" fill="#f1e9d7"/><circle cx={x+7*Math.sin(s*.7)} cy="-5" r="7" fill="#141b1d"/><circle cx={x+3} cy="-8" r="2" fill="white"/></g>)}</g>
 <path d="M-16 52q18 7 35-1" fill="none" stroke="#38281f" strokeWidth="4"/>
 {i===0&&<path d="M-80 146L-115 430H115L80 146L54 128V235H-54V128Z" fill="#243d37"/>}
