const USA='M120 640L225 668L290 687L372 700L430 706L448 680L530 690L575 670L620 710L666 685L700 730L740 706L765 755L820 740L858 706L910 698L936 665L955 702L918 753L865 790L849 835L806 849L790 878L750 896L731 936L746 1005L724 1025L700 974L665 930L602 925L561 909L522 949L491 953L457 923L430 923L409 877L347 878L310 853L269 835L243 802L208 801L180 756L154 728Z';
const MapScene=()=>{
 const {s,spr}=useS();
 const a=spr(at('siete',4));
 return <g>
 <defs><clipPath id="usclip"><path d={USA}/></clipPath></defs>
 <path d={USA} fill="#1d3033" stroke="#bcac7b" strokeWidth="6"/>
 <g clipPath="url(#usclip)">{Array.from({length:144},(_,i)=>{
 const x=130+i%16*53,y=645+Math.floor(i/16)*43;
