 })}</g>
 {Array.from({length:10},(_,i)=><g key={i} transform={`translate(${180+i%5*180} ${1140+Math.floor(i/5)*130}) scale(${.7+.05*Math.sin(s+i)})`}><rect x="-75" y="-43" width="150" height="95" rx="12" fill={i<7&&a>i/10?GOLD:'#465655'}/><rect x="-64" y="-32" width="128" height="62" rx="5" fill={i<7&&a>i/10?'#fff0a7':'#203536'}/><path d="M-20 58h40" stroke="#a4ada4" strokeWidth="5"/></g>)}
 </g>;
};

const Interior=()=>{
 const {s,lin}=useS();
 const start=at('dólar',6),stop=at('sesenta',6);
 const p=lin(start,stop,0,1);
 return <g>
 <rect x="-80" y="310" width="1240" height="1430" rx="100" fill="url(#leather)" stroke="#d29c64" strokeWidth="18"/>
 <path d="M-40 600Q540 390 1120 600V1580Q540 1420-40 1580Z" fill="#231510"/>
 <path d="M0 660Q540 470 1080 660" stroke="#b77d4d" strokeWidth="15" fill="none"/>
 {Array.from({length:9},(_,i)=>{
 const q=Math.max(0,Math.min(1,(p*10-i)/2));
 return <Bill key={i} x={540+q*(i%2?540:-540)} y={1080+i*29-q*650} r={q*(i%2?30:-30)}/>;
 })}
 <path d={`M-20 ${1350-p*130}Q540 ${1210-p*40}1100 ${1350-p*130}V1750H-20Z`} fill="url(#leather)" stroke="#c78d58" strokeWidth="9"/>
 <path d={`M20 ${1390-p*130}Q540 ${1250-p*40}1060 ${1390-p*130}`} fill="none" stroke="#d4aa7d" strokeWidth="4" strokeDasharray="10 15"/>
 </g>;
};

const Scene:React.FC<{e:number}>=({e})=>{
 const {s,lin,spr}=useS();
 const t=T(ARR[e]);
 const col=tono(s,[T(0),T(42),T(99),T(123),T(154)],['#8e603b','#a78639','#9e332e','#8b7441','#8e603b']);
 const drift=Math.sin(s*.28)*12;
 return <AbsoluteFill>
 <Textura tipo="fibra" base={`radial-gradient(ellipse at 40% 45%, ${col}, #171c1e 85%)`} linea="#24180f" luz="rgba(255,218,151,.12)" semilla={e+11}/>
 <Brillo x={510} y={950} r={650} color="rgba(255,207,104,.22)"/>
 <svg width="1080" height="1920" viewBox="0 0 1080 1920" style={{position:'absolute'}}>
 <Defs/>
 <g transform={`translate(${drift} ${Math.cos(s*.23)*7}) translate(540 1000) scale(${1+lin(t,T(ARR[e+1]??170),0,.035)}) translate(-540 -1000)`}>
 {(e===0||e===1||e===3||e===7||e===8)&&<>
 <path d="M-150 1180L1150 1100L1250 1950H-150Z" fill="#765133"/><path d="M-150 1180L1150 1100" stroke="#b98b57" strokeWidth="16"/>
 {Array.from({length:18},(_,i)=><path key={i} d={`M-80 ${1230+i*41}Q500 ${1150+i*47}1170 ${1200+i*40}`} fill="none" stroke={i%2?'#a17448':'#4d3527'} strokeWidth={i%3?3:8} opacity=".45"/>)}
 {[0,1,2,3,4].map(i=><g key={i} transform={`translate(${100+i*200} ${1540+i%2*70}) rotate(${i*32})`}><ellipse rx="17" ry="27" fill="#34231b"/><path d="M0-23q-8 22 0 47" stroke="#b28758" strokeWidth="3" fill="none"/></g>)}
 </>}
 {e===0&&<Tablet e={e}/>}
 {e===1&&<>
 <g opacity=".4"><ellipse cx="250" cy="600" rx="200" ry="40" fill="#a08660"/><path d="M210 630v260m80-260v260" stroke="#443c31" strokeWidth="24"/></g>
 <g transform={`translate(${lin(t,at('llevar',1),-500,0)} 0)`}><Coffee x={250} y={1220} scale={.95}/></g>
 <g transform="translate(250 -100) scale(.75)"><Tablet e={e}/></g>
 </>}
 {e===2&&<Queue/>}
 {e===3&&<><Tablet e={e}/><Finger x={550+lin(at('tocas',3),at('medio',3),110,0)} y={1000+lin(t,at('tocas',3),460,0)} scale={.9}/></>}
 {e===4&&<MapScene/>}
 {e===5&&<>
 <path d="M-100 1270L1200 1210V1920H-100Z" fill="#60422c"/>
 {[0,1,2,3].map(i=><Coffee key={i} x={160+i*252} y={1100+Math.sin(s+i)*7} scale={.83} lit={i===0&&s>=at('uno',5)}/>)}
 <g opacity={spr(at('uno',5))} transform={`translate(160 ${720+Math.sin(s*2)*9})`}><circle r="64" fill="url(#gold)" stroke="#ffec9a" strokeWidth="7"/><text y="19" textAnchor="middle" fontSize="54" fill="#70551f" fontFamily={FONT}>$1</text></g>
 </>}
 {e===6&&<Entrar t={at('suma',6)} x={540} y={1100} dur={.9} zoom={12} fuera={<Wallet x={540} y={1100} scale={1.25}/>} dentro={<Interior/>}/>}
 {e===7&&<><Tablet e={e}/><Finger x={760} y={1150+lin(at('otra',7),at('escribe',7),100,0)} scale={.7}/></>}
 {e===8&&<Tablet e={e}/>}
 {e!==6&&e!==2&&<Wallet x={810} y={1620} scale={.45} thin={e>=7?1:0}/>}
 </g>
 </svg>
 {e===4&&<Chip texto="72 %" x={540} y={490} t0={at('siete',4)} color={GOLD} size={72}/>}
 {e===5&&<Chip texto="25 %" x={540} y={490} t0={at('cuatro',5)} color={GOLD} size={72}/>}
 {e===6&&<Contador desde={0} hasta={260} t0={at('dólar',6)} t1={at('sesenta',6)} x={540} y={550} prefijo="$" color="#FF4D4D" size={110}/>}
 <Profundidad color="rgba(26,15,8,.28)" lejos="rgba(255,224,157,.10)" semilla={e+3} manchas={3} deriva={.35}/>
 </AbsoluteFill>;
};

export const Escena:React.FC=()=>{
 const {s}=useS();
 let e=0;for(let i=1;i<ARR.length;i++)if(s>=T(ARR[i]))e=i;
 // Los cambios de lugar conservan su motivo del plan; la cartera usa Entrar en «suma».
 if(e===3&&s<T(42)+.3)return <Paso t={T(42)} tipo="barrido" dur={.55} antes={<Scene e={2}/>} despues={<Scene e={3}/>}/>;
 if(e===4&&s<T(62)+.4)return <Paso t={T(62)} tipo="alejar" dur={.7} antes={<Scene e={3}/>} despues={<Scene e={4}/>}/>;
 return <Scene e={e}/>;
};
